 const nav=$('#reader-content .culture-mode-nav');if(nav){$('#library-culture-nav').replaceChildren(nav);}else if(readerArea!=='culture')$('#library-culture-nav').replaceChildren();
 $('#reader-content').classList.toggle('library-overview',readerTab==='culture'&&readerCultureMode==='overview');$('#reader-settings').hidden=readerTab==='culture'&&readerCultureMode==='overview';$('#reader-index').hidden=readerTab==='culture'&&readerCultureMode==='overview';$('#reader-back-top').textContent=readerTab==='culture'&&readerCultureMode==='overview'?'阅读导航 ↑':'导航与检索 ↑';$('#reader-search').placeholder=readerArea==='archive'?'检索原始主题、人物或笔记':readerTab==='culture'?'检索当前阅读方式中的内容':'检索人物、地点、事件或正文';
