function libraryFoldArticle(card,entry,selector,open){const head=selector==='profile'?2:3,children=Array.from(card.childNodes).slice(head);const fold=historyEl('details',null,selector==='profile'?'reader-profile-body':'culture-article-body');const articleKey=selector+':'+entry.id;fold.dataset.libraryArticle=articleKey;fold.open=Boolean(open)||libraryOpenedArticles.has(articleKey);fold.append(historyEl('summary',selector==='profile'?'阅读完整小传与相关内容':'阅读全文 · 概念、论证与出处'));children.forEach(n=>fold.append(n));const lead=entry.sections?.[0]?.text||'';card.append(historyEl('p',lead.length>120?lead.slice(0,120)+'…':lead,'library-card-abstract'),fold);fold.addEventListener('toggle',()=>{if(!fold.isConnected)return;if(fold.open)libraryOpenedArticles.add(articleKey);else libraryOpenedArticles.delete(articleKey);if(libraryLastState)libraryLastState.openArticles=[...libraryOpenedArticles];});fold.querySelector('summary').addEventListener('click',()=>{if(!fold.open)rememberReader(selector==='profile'?'people':'culture',entry.id);});return card;}
function libraryOpenTarget(target){const fold=target?.querySelector('.culture-article-body,.reader-profile-body');if(fold){fold.open=true;libraryOpenedArticles.add(fold.dataset.libraryArticle);}}
function bindReadingLibrary(){
 if(typeof bindReadingUnity==='function')bindReadingUnity();
 matchMedia('(min-width:761px)').addEventListener('change',event=>{if(event.matches)$('#library-menu').open=true;});
 $('#library-archive').addEventListener('click',()=>librarySetMode('tree'));$('#library-history-start').addEventListener('click',()=>librarySelectTab('events'));$('#library-back').addEventListener('click',libraryGoBack);$('#open-reading-library').addEventListener('click',openReadingLibrary);$('#reader-back-top').addEventListener('click',()=>{$('#library-menu').open=true;});$('#comparison-reader-dialog').addEventListener('scroll',()=>{if(libraryLastState)libraryLastState.scroll=$('#comparison-reader-dialog').scrollTop;},{passive:true});
}
